from pathlib import Path
import csv,hashlib,json,os,shutil,subprocess,time
R=Path.cwd();B=R/'build/crow-implicit-drive-audit-build-01';A=R/'artifacts/crow-rl-implicit-drive-audit-20261108';T=R/'.numi/retained-runtime/implicit-drive-audit-20261108'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2,sort_keys=True)+'\n')
assert not subprocess.check_output(['git','status','--porcelain'])
A.mkdir(exist_ok=False)
cal=json.loads((B/'calibration.stdout').read_text());assert cal['model_valid'] and cal['scalar_closed_form_vs_bisection_256_max_velocity_error']<1e-12
assert cal['fp64_mass_acceleration_error']<1e-8
inputs=[B/'probe',B/'probe.cpp',T/'libmetalrobo.dylib',T/'metalrobo/MetalRobo.metallib',R/'src/metal/MetalWorld.metal',R/'src/metal/ArticulatedABA.metal',R/'src/metal/ArticulatedParallelABA.metal',R/'src/metal/ArticulatedInverseMass.metal',R/'src/metal/MetalWorldContact.metal',R/'src/metal/MetalWorld.mm',R/'include/metalrobo/engine_types.h']
plan={'purpose':'Mechanism qualification of the native torque-limited implicit position drive; diagnose a possible source of cadence dependence without claiming the crow release root cause.','question':'Does clamping the pre-integration drive before applying unconditional implicit mass augmentation disagree with the actual saturated backward-Euler drive equation?','source_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'mechanism':'Current refresh clamps K(target-q-h*v)-D*v; ABA always augments inertia by hD+h^2K. Saturating implicit dynamics instead requires M*(v_next-v)/h=clip(K*(target-q-h*v_next)-D*v_next, +/-limit).','alternatives':['The named implicit mode may intentionally define a different approximate saturation algorithm; that still requires explicit semantics and numerical qualification.','Crow release differences may additionally arise from contact integration, friction, other actuators or event segmentation. This isolated result cannot resolve their contributions.'],'model':'Fixed-root single revolute hinge, COM at hinge, inertia4e-6kg*m2 plus armature2e-6, K=.30Nm/rad,D=.015Nm*s/rad,limit=.01Nm; no body damping/gravity/colliders/profile/native task. Stored FP32 parameters are promoted to FP64 for predictions.','conditions':{'initial_states':'Eight deterministic named lanes: neutral, tiny positive error, small damped velocity, positive/negative saturated error, two opposing initial velocities under saturation, and offset same-target damped motion.','durations_seconds':[float(.02/n) for n in (16,32,64,128)],'paths':['freeMotionABA CCD disabled','temporalCone CCD disabled','temporalCone hybrid CCD, no contact/events'],'replication':'Deterministic mechanism conditions, not biological or independent training replicates; no statistical population inference.'},'prediction':{'all96_native_rows_match_current_clamp_then_augmented_inertia_formula_absolute_velocity_error_max':2e-6,'all48_unsaturated_controls_match_independent_saturated_backward_Euler_velocity_max_absolute_error':2e-6,'all24_zero_initial_velocity_saturated_cases_have_realized_torque_deficit_fraction_at_least':.25,'native_q_matches_q_plus_h_vnext_absolute_error_max':2e-7},'refutation':'Any valid observation violating a prediction contradicts that part. Native rejection/missing row or failed mass/reference calibration makes the study inconclusive. All outcomes retained.','calibration':cal,'inputs':{str(p.relative_to(R)):sha(p) for p in inputs},'command':['build/crow-implicit-drive-audit-build-01/probe','.numi/retained-runtime/implicit-drive-audit-20261108/metalrobo/MetalRobo.metallib','build/crow-implicit-drive-audit-build-01/native.tsv'],'budget':{'native_invocations':1,'native_one_microstep_environments':96,'timeout_seconds':90,'new_output_max_bytes':1000000,'stop':'One invocation, no retries/tuning. No native source change, new crow motor trial or deployment promotion.'},'notebook':'tools/numi science unavailable (unknown capability); equivalent sealed Git plan, exact inputs/calibration, native command/raw observations and revisions retained.'}
write(A/'plan.json',plan)
for src in (B/'probe.cpp',B/'run.py'):shutil.copy2(src,A/src.name)
subprocess.run(['git','add',str(A)],check=True);subprocess.run(['git','commit','-m','Seal isolated native implicit-drive saturation diagnosis'],check=True);subprocess.run(['git','push','origin','HEAD'],check=True)
for p,h in plan['inputs'].items():assert sha(R/p)==h
env=os.environ.copy();env.update(DYLD_LIBRARY_PATH=str(T),DYLD_PRINT_LIBRARIES='1')
cmd=[B/'probe',T/'metalrobo/MetalRobo.metallib',B/'native.tsv'];start=time.monotonic()
with (B/'native.stdout').open('xb') as out,(B/'native.stderr').open('xb') as err:
    code=subprocess.run([str(x) for x in cmd],env=env,stdout=out,stderr=err,timeout=90).returncode
receipt={'command':[str(x) for x in cmd],'exit_code':code,'seconds':time.monotonic()-start};write(B/'execution.json',receipt)
report={'execution':receipt,'native_source_changed':False,'profile_or_policy_promoted':False}
if code!=0:
    report.update(verdict='inconclusive_native_instrument_failure',failure='Inspect native.stderr; no retry.');write(A/'results.json',report);print(json.dumps(report),flush=True);raise SystemExit(1)
rows=[{k:float(v) for k,v in r.items()} for r in csv.DictReader((B/'native.tsv').open(),delimiter='\t')];assert len(rows)==96
def clip(v,t):return max(-t,min(t,v))
analysis=[]
for r in rows:
    M,K,D,Tau,h,q,v,t=[r[k] for k in ('mass','k','d','limit','h','q','v','target')]
    denom=M+h*D+h*h*K;pre=K*(t-q-h*v)-D*v
    current=v+h*clip(pre,Tau)/denom
    linear=(M*v+h*K*(t-q))/denom;exact=max(v-h*Tau/M,min(v+h*Tau/M,linear))
    realized=M*(r['final_v']-v)/h;want=clip(K*(t-r['final_q'])-D*r['final_v'],Tau)
    analysis.append(r|{'pre_drive':pre,'clamp_then_augmented_inertia_predicted_v':current,'saturated_backward_Euler_predicted_v':exact,'native_current_formula_velocity_error':abs(r['final_v']-current),'native_saturated_backward_Euler_velocity_error':abs(r['final_v']-exact),'q_integration_error':abs(r['final_q']-(q+h*r['final_v'])),'realized_torque':realized,'backward_Euler_drive_torque':want,'drive_equation_residual_Nm':realized-want,'torque_deficit_fraction':1-abs(realized)/Tau})
unsat=[r for r in analysis if int(r['lane']) in (0,1,2,7)];sat_zero=[r for r in analysis if int(r['lane']) in (3,4)]
checks={'all96_match_current_formula':max(r['native_current_formula_velocity_error'] for r in analysis)<=2e-6,'all48_unsaturated_match_saturated_implicit_reference':len(unsat)==48 and max(r['native_saturated_backward_Euler_velocity_error'] for r in unsat)<=2e-6,'all24_rest_saturated_torque_deficits_at_least25percent':len(sat_zero)==24 and min(r['torque_deficit_fraction'] for r in sat_zero)>=.25,'all_q_integrations_match':max(r['q_integration_error'] for r in analysis)<=2e-7}
loaded=[s for s in (B/'native.stderr').read_text().splitlines() if s.startswith('dyld[') and 'libmetalrobo.dylib' in s];assert loaded and all(s.endswith(str(T/'libmetalrobo.dylib')) for s in loaded)
report.update(verdict='predicted_saturation_equation_disagreement_confirmed' if all(checks.values()) else 'prediction_contradicted',checks=checks,row_count=len(rows),actual_loader_lines=loaded,maximum_current_formula_velocity_error=max(r['native_current_formula_velocity_error'] for r in analysis),maximum_unsaturated_reference_velocity_error=max(r['native_saturated_backward_Euler_velocity_error'] for r in unsat),minimum_saturated_rest_torque_deficit_fraction=min(r['torque_deficit_fraction'] for r in sat_zero),maximum_saturated_reference_velocity_error=max(r['native_saturated_backward_Euler_velocity_error'] for r in analysis),positive_rest_by_cadence=[r for r in analysis if r['path']==2 and r['lane']==3],limits='Isolated one-joint equations only. Does not establish the cause or resolution of full crow release cadence error.')
write(A/'results.json',report);write(B/'analysis.json',analysis)
print(json.dumps(report,indent=2),flush=True)
